        ///   </para>
        ///   <para>
        ///     C++:
        ///     <see href="https://github.com/jrouwe/JoltPhysics/blob/e77f175595e64cb44218cc9d9d56fc365ad0e36a/Jolt/Geometry/Indexify.h#L14">Jolt/Geometry/Indexify.h:14</see>
