        ///     <c>void Indexify(const TriangleList &amp;inTriangles, VertexList &amp;outVertices, IndexedTriangleList &amp;outTriangles, float inVertexWeldDistance = 1.0e-4f)</c>
        ///   </para>
        /// </summary>
        /// <remarks>
        ///   <para>
        ///     inTriangles is copied into a native container for the call; the span is only read.
        ///   </para>
        ///   <para>
        ///     outVertices is an owned native buffer - read it through AsSpan() and Dispose it when you are done with
        ///     it.
        ///   </para>
        ///   <para>
        ///     outTriangles is an owned native buffer - read it through AsSpan() and Dispose it when you are done with
        ///     it.
        ///   </para>
        /// </remarks>
        public static unsafe void Indexify(
            ReadOnlySpan<Triangle> inTriangles,
            out NativeArray<float3> outVertices,
            out NativeArray<IndexedTriangle> outTriangles,
            float inVertexWeldDistance = 0.0001f
        )
        {
            fixed (Triangle* inTriangles_fixed = inTriangles)
            {
                Jolt.PInvoke.Indexify(
                    inTriangles_fixed,
                    (nuint)inTriangles.Length,
                    out var outVertices_raw,
                    out var outTriangles_raw,
                    inVertexWeldDistance
                );
                outVertices = new NativeArray<float3>(outVertices_raw);
                outTriangles = new NativeArray<IndexedTriangle>(outTriangles_raw);
            }
        }

        /// <summary>
        ///   <para>
        ///     Take a list of indexed triangles and unpack them
        ///   </para>
        ///   <para>
        ///     C++:
        ///     <see href="https://github.com/jrouwe/JoltPhysics/blob/e77f175595e64cb44218cc9d9d56fc365ad0e36a/Jolt/Geometry/Indexify.h#L17">Jolt/Geometry/Indexify.h:17</see>
        ///     <br/>
        ///     <c>void Deindexify(const VertexList &amp;inVertices, const IndexedTriangleList &amp;inTriangles, TriangleList &amp;outTriangles)</c>
        ///   </para>
        /// </summary>
        /// <remarks>
        ///   <para>
        ///     inVertices is copied into a native container for the call; the span is only read.
        ///   </para>
        ///   <para>
        ///     inTriangles is copied into a native container for the call; the span is only read.
        ///   </para>
        ///   <para>
        ///     Returns an owned native buffer - read it through AsSpan() and Dispose it when you are done with it.
        ///   </para>
        /// </remarks>
        public static unsafe NativeArray<Triangle> Deindexify(
            ReadOnlySpan<float3> inVertices,
            ReadOnlySpan<IndexedTriangle> inTriangles
        )
        {
            fixed (IndexedTriangle* inTriangles_fixed = inTriangles)
            fixed (float3* inVertices_fixed = inVertices)
            {
                Jolt.PInvoke.Deindexify(
                    inVertices_fixed,
                    (nuint)inVertices.Length,
                    inTriangles_fixed,
                    (nuint)inTriangles.Length,
                    out var outTriangles_raw
                );
                return new NativeArray<Triangle>(outTriangles_raw);
            }
        }

