        ) =>
            Jolt.PInvoke.EstimateCollisionResponse(
                body1,
                body2,
                in manifold,
                ref result,
                combinedFriction,
                combinedRestitution,
                minVelocityForRestitution,
                numIterations
            );

        /// <summary>
        ///   <para>
        ///     C++:
        ///     <see href="https://github.com/jrouwe/JoltPhysics/blob/e77f175595e64cb44218cc9d9d56fc365ad0e36a/Jolt/Physics/Collision/ManifoldBetweenTwoFaces.h#L20">Jolt/Physics/Collision/ManifoldBetweenTwoFaces.h:20</see>
        ///     <br/>
        ///     <c>void PruneContactPoints(Vec3Arg inPenetrationAxis, ContactPoints &amp;ioContactPointsOn1, ContactPoints &amp;ioContactPointsOn2</c>
        ///   </para>
        /// </summary>
        /// <remarks>
        ///   <para>
        ///     Throws ArgumentException for contactPointsOn1: "contactPointsOn1 must hold more than 4 points (at most
        ///     64); with 4 or fewer there's nothing to prune." Throws ArgumentException for contactPointsOn2:
        ///     "contactPointsOn2 must hold as many points as contactPointsOn1."
        ///   </para>
        /// </remarks>
        public static void PruneContactPoints(
            float3 penetrationAxis,
            ref StaticArrayVec3_64 contactPointsOn1,
            ref StaticArrayVec3_64 contactPointsOn2,
            float3 centerOfMass
        )
        {
            Jolt.PInvoke.PruneContactPoints(
                penetrationAxis,
                ref contactPointsOn1,
                ref contactPointsOn2,
                centerOfMass,
                out var _bufferCheck
            );
            if (_bufferCheck == 1)
                throw new ArgumentException(
                    "contactPointsOn1 must hold more than 4 points (at most 64); with 4 or fewer there's nothing to prune.",
                    nameof(contactPointsOn1)
                );
            if (_bufferCheck == 2)
                throw new ArgumentException(
                    "contactPointsOn2 must hold as many points as contactPointsOn1.",
                    nameof(contactPointsOn2)
                );
        }

        /// <summary>
        ///   <para>
        ///     C++:
        ///     <see href="https://github.com/jrouwe/JoltPhysics/blob/e77f175595e64cb44218cc9d9d56fc365ad0e36a/Jolt/Physics/Collision/ManifoldBetweenTwoFaces.h#L38">Jolt/Physics/Collision/ManifoldBetweenTwoFaces.h:38</see>
        ///     <br/>
        ///     <c>void ManifoldBetweenTwoFaces(Vec3Arg inContactPoint1, Vec3Arg inContactPoint2, Vec3Arg inPenetrationAxis, float inMaxContactDistance, const ConvexShape::SupportingFace &amp;inShape1Face, const ConvexShape::SupportingFace &amp;inShape2Face, ContactPoints &amp;outContactPoints1, ContactPoints &amp;outContactPoints2</c>
        ///   </para>
        /// </summary>
        /// <remarks>
        ///   <para>
        ///     shape1Face is copied into a fixed 32-element native container for the call; anything past that is
        ///     ignored.
        ///   </para>
        ///   <para>
        ///     shape2Face is copied into a fixed 32-element native container for the call; anything past that is
        ///     ignored.
        ///   </para>
        /// </remarks>
        public static unsafe void ManifoldBetweenTwoFaces(
            float3 contactPoint1,
            float3 contactPoint2,
            float3 penetrationAxis,
            float maxContactDistance,
            ReadOnlySpan<float3> shape1Face,
            ReadOnlySpan<float3> shape2Face,
            out StaticArrayVec3_64 contactPoints1,
            out StaticArrayVec3_64 contactPoints2,
            float3 centerOfMass
        )
        {
            fixed (float3* shape2Face_fixed = shape2Face)
            fixed (float3* shape1Face_fixed = shape1Face)
            {
                Jolt.PInvoke.ManifoldBetweenTwoFaces(
                    contactPoint1,
                    contactPoint2,
                    penetrationAxis,
                    maxContactDistance,
                    shape1Face_fixed,
                    (nuint)shape1Face.Length,
                    shape2Face_fixed,
                    (nuint)shape2Face.Length,
                    out contactPoints1,
                    out contactPoints2,
                    centerOfMass
                );
            }
        }

