        /// <summary>
        ///   <para>
        ///     Installs the function Jolt calls when one of its asserts fails, and returns whether the loaded natives
        ///     have asserts at all - only Debug natives, or ones built with JOLT_DEBUG, do. The handler gets the failed
        ///     expression, an optional message (may be null), and the file and line as UTF-8 C strings; returning true
        ///     breaks into the debugger, false carries on as a release build would. It runs on whichever thread
        ///     asserted, Jolt's workers included, so it must be a static method marked [UnmanagedCallersOnly(CallConvs
        ///     = [typeof(CallConvCdecl)])] and must not throw. Pass null to put back Jolt's default, which breaks. Jolt
        ///     reads the hook unsynchronised, so set it while no physics update is running.
        ///   </para>
        /// </summary>
        public static unsafe bool SetAssertHandler(
            delegate* unmanaged[Cdecl]<byte*, byte*, byte*, uint, Brutal.Bool8> handler
        ) => Jolt.PInvoke.SetAssertHandler(handler);

        /// <summary>
        ///   <para>
        ///     Installs the function Jolt's log messages go to, as a formatted UTF-8 C string (at most 1023 bytes). It
        ///     runs on whichever thread logged, Jolt's workers included, so it must be a static method marked
        ///     [UnmanagedCallersOnly(CallConvs = [typeof(CallConvCdecl)])], thread-safe, and must not throw. Pass null
        ///     to drop the messages. Either way Jolt's own default, which asserts, is replaced - so natives built with
        ///     asserts don't treat a log line as a failure. Call it before the first physics update: swapping handlers
        ///     later is safe, but the first call installs Jolt's trace hook, which Jolt itself only expects to change
        ///     while nothing is running.
        ///   </para>
        /// </summary>
        public static unsafe void SetTraceHandler(delegate* unmanaged[Cdecl]<byte*, void> handler) =>
            Jolt.PInvoke.SetTraceHandler(handler);
